Looking at the examples, I notice that:

1. The grids have **two mirror symmetry axes** (one horizontal, one vertical), with `9` values marking "corrupted" cells
2. Each `9` cell can be restored using the grid's symmetry - by reflecting across the row axis, column axis, or both (180° rotation)
3. The axes are found by checking which axis value makes all non-9 mirror pairs consistent

For each `9` cell, I try: row mirror → column mirror → 180° rotation, using whichever gives a valid non-9 source.

```python
def solve(grid):
    nr = len(grid)
    nc = len(grid[0])

    def find_axis(is_row):
        n = nr if is_row else nc
        m = nc if is_row else nr
        best = None
        best_score = -1
        for a2 in range(1, 2 * n):
            score = 0
            ok = True
            for i in range(n):
                j = a2 - i
                if j <= i or j >= n:
                    continue
                for k in range(m):
                    v1 = grid[i][k] if is_row else grid[k][i]
                    v2 = grid[j][k] if is_row else grid[k][j]
                    if v1 == 9 or v2 == 9:
                        continue
                    if v1 != v2:
                        ok = False
                        break
                    score += 1
                if not ok:
                    break
            if ok and score > best_score:
                best_score = score
                best = a2
        return best

    ra = find_axis(True)
    ca = find_axis(False)

    result = [row[:] for row in grid]
    for r in range(nr):
        for c in range(nc):
            if grid[r][c] != 9:
                continue
            if ra is not None:
                r2 = ra - r
                if 0 <= r2 < nr and grid[r2][c] != 9:
                    result[r][c] = grid[r2][c]
                    continue
            if ca is not None:
                c2 = ca - c
                if 0 <= c2 < nc and grid[r][c2] != 9:
                    result[r][c] = grid[r][c2]
                    continue
            if ra is not None and ca is not None:
                r2, c2 = ra - r, ca - c
                if 0 <= r2 < nr and 0 <= c2 < nc and grid[r2][c2] != 9:
                    result[r][c] = grid[r2][c2]

    return result
